import boto3
import parse

if not isinstance(output_dir, Dir):
    raise ValueError("The provided output_dir isn't a Dir Object.")
if output_dir.url is None:
    return

obj = parse.urlparse(output_dir.url)
if obj.scheme != "s3":
    raise ValueError(f"The provided folder should start with s3://. Found {output_dir.url}.")

s3 = boto3.client("s3")
prefix = obj.path.lstrip("/").rstrip("/") + "/"

objects = s3.list_objects_v2(Bucket=obj.netloc, Delimiter="/", Prefix=prefix)

if "index.json" in [obj["Key"] for obj in objects["Contents"]]:
    raise ValueError(f"The directory {prefix} already contains an index file.")

for obj in objects["Contents"]:
    if obj["Key"] != "index.json":
        s3.delete_object(Bucket=obj.netloc, Key=obj["Key"])

